function getIbmQradarTranslation(key, lang) {
    return (ibmqradarTranslations[lang] && ibmqradarTranslations[lang][key]) ||
           (ibmqradarTranslations.en && ibmqradarTranslations.en[key]) || null;
}

function applyIbmQradarTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.ibm-qradar.") || key.startsWith("review.common."))) {
            const translation = getIbmQradarTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} ibm-qradar translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyIbmQradarTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyIbmQradarTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyIbmQradarTranslations(window.i18n?.getCurrentLanguage() || "en");
}
